/**
 * @name Tainted data flowing into Python eval/exec in Jinja2
 * @description Detects whether untrusted (remote) data can reach eval/exec or similar dynamic code execution in the Jinja2 package.
 * @kind path-problem
 * @problem.severity error
 * @id py/jinja2/remote-to-eval
 * @tags security
 *       external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module Jinja2EvalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(CodeExecution ce |
      sink = ce.getCode()
    )
  }
}

module Jinja2EvalFlow = TaintTracking::Global<Jinja2EvalConfig>;
import Jinja2EvalFlow::PathGraph

from Jinja2EvalFlow::PathNode source, Jinja2EvalFlow::PathNode sink
where Jinja2EvalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data reaches dynamic code execution $@.", source.getNode(), "user input"

